fi
for book in "$@"; do
  case "$book" in
    ''|*[!a-z0-9-]*) printf 'Invalid book name: %s\n' "$book" >&2; exit 1 ;;
  esac
done
cert_books=("$@")
cert_total=${#cert_books[@]}
cert_batch_size=12
touch "$started_path"
: > "$log_path"
for ((cert_offset=0; cert_offset<cert_total; cert_offset+=cert_batch_size)); do
  cert_batch=("${cert_books[@]:cert_offset:cert_batch_size}")
  printf 'Certification batch %d of %d (%d books)\n' \
    "$((cert_offset/cert_batch_size+1))" "$(((cert_total+cert_batch_size-1)/cert_batch_size))" \
    "${#cert_batch[@]}" >> "$log_path"
  if ! {
    printf '(set-cbd "%s/acl2/")\n' "$task_root"
    for book in "${cert_batch[@]}"; do
      printf '(certify-book "%s" 0)\n(ubt! 1)\n' "$book"
    done
    printf '(good-bye)\n'
  } | timeout 300 bash "$task_root/acl2/run-wsl.sh" >> "$log_path" 2>&1; then
    tail -n 100 "$log_path"
    exit 1
  fi
  for book in "${cert_batch[@]}"; do
    if [ ! "$task_root/acl2/$book.cert" -nt "$started_path" ]; then
      tail -n 100 "$log_path"
      exit 1
    fi
  done
done
printf 'Certified %s. Log: %s\n' "${cert_books[*]}" "$log_path"
